-- ---------------------------------------------------------------- 1. the signed Customer Terms (trg_pages_legal_sync carries it)
update public.pages set html = $qd_customer_terms$<style id="qdmf">html,body{overflow-x:hidden;max-width:100%}.body{overflow-wrap:anywhere;word-break:break-word}.body table{display:block;width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch}.body img{max-width:100%;height:auto}</style><h1>Terms of Service</h1><div class="muted">For customers using QuotesDone to request quotes and reveal suppliers.</div><div class="card"><p>These Terms and Conditions (&quot;Terms&quot;) govern your use of the QuotesDone platform as a customer. QuotesDone is the online platform operated by QuotesDone Technologies, a Sole Establishment licensed by the Dubai Department of Economy and Tourism (Trader License No. 1633275), Dubai, United Arab Emirates (&quot;QuotesDone&quot;, &quot;we&quot;, &quot;us&quot;). QuotesDone is an online B2B sourcing marketplace operated in Dubai, United Arab Emirates. By creating an account, submitting a request for quotations, or paying a reveal fee, you accept these Terms. Acceptance by electronic means (including click-acceptance) is valid and binding under Federal Decree-Law No. 46 of 2021 on Electronic Transactions and Trust Services.</p><h2>1. Definitions</h2><p>&quot;Platform&quot; means the QuotesDone website, applications and services. &quot;Customer&quot;, &quot;you&quot; means the business or individual requesting quotations. &quot;Supplier&quot; means a vetted third-party provider that submits quotations. &quot;Inquiry&quot; means a request for quotations you submit. &quot;Quote&quot; means an anonymised quotation from a Supplier. &quot;Reveal&quot; means unlocking the identity and contact details of a chosen Supplier. &quot;Reveal Fee&quot; and &quot;card processing fee&quot; have the meanings in clause 4.</p><h2>2. The service and how anonymous quoting works</h2><p>QuotesDone lets you describe a job (by text, voice, photo or drawing). Our system structures your request and matches it to vetted Suppliers, who submit competing quotations on an anonymised basis - you can compare prices and scope without any party&#x27;s identity being disclosed.</p><p>QuotesDone is a marketplace and facilitator only. It is not a contractor, supplier, agent or party to any contract for the works. Quotes are prepared by independent Suppliers who are solely responsible for their pricing, scope and performance.</p><h2>3. Account and eligibility</h2><p>You must provide accurate registration details and keep your account secure. You are responsible for activity under your account. You must be authorised to procure the services you request.</p><h2>4. Reveal Fee (3%, no cap), card processing fee and VAT</h2><p>Posting a request and comparing quotes is free. You pay only when you choose to reveal a Supplier you wish to engage.</p><p>The Reveal Fee is three percent (3%) of the value of the selected quotation. There is NO maximum cap on the Reveal Fee. With the Reveal Fee you also pay a card processing fee: the fee our payment processor charges to take your payment, calculated so that QuotesDone receives the full Reveal Fee. Before you confirm payment you are shown the Reveal Fee, the card processing fee and the total you will pay, in AED.</p><p>The Reveal Fee and the card processing fee are paid through the Platform (card or Apple Pay) in one payment, charged once per reveal. Revealing a Supplier does not create any contract between you and QuotesDone for the underlying works; it unlocks the Supplier&#x27;s identity so you may contract with them directly.</p><p>QuotesDone is not registered for VAT, so no VAT is charged on the Reveal Fee or the card processing fee. If QuotesDone registers for VAT, it will tell you before any VAT is charged; VAT will then apply only to reveals paid after that date and will be shown on a valid tax invoice issued under Federal Decree-Law No. 8 of 2017. The total shown before you pay is the full amount, with no hidden or further charges for the reveal.</p><h2>5. Refunds, immediate performance and complaints about non-responsive suppliers</h2><p>You expressly request that QuotesDone perform the Reveal immediately upon payment, and you acknowledge that the service &mdash; disclosure of the Supplier&#39;s identity and contact details &mdash; is fully performed and delivered electronically at the moment of Reveal. Once the Reveal has been delivered, any right to cancel before delivery is exhausted and the Reveal Fee and card processing fee are earned. They are not automatically refundable, and there is no self-service refund.</p><p>If, after a Reveal, the Supplier does not respond to you, you do not need to do anything for the clock to start: QuotesDone tracks every Reveal from the moment you pay. If the Supplier has not responded within three (3) working days of your payment, QuotesDone chases the Supplier on your behalf, copying you. If there is still no response by the fifth (5th) working day, the case goes to QuotesDone&#39;s CEO for a final call. You may also raise a complaint through the Platform at any time; contacting the Supplier in writing (for example by email) and copying supplier@quotesdone.com puts your own attempt to reach the Supplier on record.</p><p>If the Supplier has failed to respond both to you and to QuotesDone within five (5) working days of your payment and does not respond to the CEO&#39;s final call, everything you paid for that Reveal is refunded: the Reveal Fee and the card processing fee. QuotesDone deducts nothing from the refund and bears any payment processing cost itself. Every refund is decided by QuotesDone&#39;s CEO and recorded against your refund case reference, which we quote to you when we confirm the outcome; no refund is automatic and there is no self-service refund. Once a refund is issued, banks and card issuers usually take seven (7) to fourteen (14) working days to show it on your statement. Working days are Monday to Friday, excluding UAE public holidays.</p><p>A Supplier is treated as having &quot;responded&quot; if they reply by any reasonable means, including the on-platform message thread, telephone, email or WhatsApp. No refund, re-match or credit is due where: the Supplier has responded; you have already engaged, contracted with, or contacted the Supplier outside the Platform other than the complaint email described above; the same Supplier was revealed to you previously; you are dissatisfied with the Supplier&#39;s price, quotation or terms; or you have simply changed your mind. QuotesDone may decline or limit repeated requests that indicate misuse of this policy.</p><p>Nothing in this section removes any right you have that cannot be excluded under the Consumer Protection Law of the United Arab Emirates.</p><h2>6. Anonymity and non-circumvention</h2><p>Anonymity is the core of the service. You agree not to seek, accept or use any means to identify or contact a Supplier off-platform before a paid reveal, and not to use the Platform to obtain Supplier identities and then transact off-platform to avoid the Reveal Fee.</p><p>Quotes and any attachments are provided for your evaluation only and must not be shared in a manner that circumvents the Platform.</p><h2>7. Customer obligations and acceptable use</h2><p>You agree to provide accurate information, use the Platform lawfully, not submit fraudulent or abusive inquiries, and not misuse, scrape, or interfere with the Platform or other users&#x27; data.</p><h2>8. No warranty on supplier works; independent contractors</h2><p>Suppliers are independent third parties. QuotesDone does not guarantee the quality, legality, safety or completion of any works, nor the accuracy of any Quote. Any contract for the works is solely between you and the Supplier. You are responsible for your own due diligence before engaging a Supplier.</p><h2>9. Liability</h2><p>To the maximum extent permitted by UAE law, QuotesDone&#x27;s total liability arising out of or in connection with the Platform is limited to the total Reveal Fees you paid in the three (3) months preceding the event giving rise to the claim. QuotesDone is not liable for indirect or consequential loss, or for the acts, omissions or works of any Supplier.</p><p>Nothing in these Terms limits or excludes liability for fraud, gross negligence, death or personal injury caused by negligence, or any liability that cannot be limited or excluded under UAE law, including non-waivable consumer rights.</p><h2>10. Data protection</h2><p>QuotesDone Technologies (Trader License No. 1633275), the operator of the Platform, is the data controller. We process personal data in accordance with the UAE Personal Data Protection Law (Federal Decree-Law No. 45 of 2021), on the lawful bases of performance of a contract, our legitimate business interests, and your consent where required, and we may use service providers (including outside the UAE) under appropriate safeguards. You may exercise your rights of access, correction, deletion and objection, and raise complaints, as set out in our Privacy Policy.</p><p>Electronic communications: we send transactional messages (one-time passwords, request and quote notifications, and account or payment confirmations) as part of providing the service; these are not marketing. We send marketing or promotional messages by email or SMS only with your consent, and you may opt out at any time. Electronic communications are handled in line with the rules of the Telecommunications and Digital Government Regulatory Authority (TDRA) and the Electronic Transactions and Trust Services Law, Federal Decree-Law No. 46 of 2021.</p><h2>11. Consumer rights</h2><p>Where the Consumer Protection Law (Federal Law No. 15 of 2020) and Cabinet Resolution No. 66 of 2023 apply, your statutory rights are preserved and prevail over any inconsistent provision of these Terms.</p><h2>12. Suspension and termination</h2><p>QuotesDone may suspend or terminate access for breach of these Terms, suspected fraud or circumvention, or as required by law. You may stop using the Platform at any time; fees already incurred remain payable.</p><h2>13. Changes to these Terms</h2><p>QuotesDone may update these Terms from time to time. Material changes will be notified through the Platform or by email and take effect prospectively.</p><h2>14. AI-generated content and platform outputs</h2><p>QuotesDone uses automated and AI-based tools to interpret your requirements, generate bills of quantities and cost estimates, standardise and compare quotations, and power support assistants. These outputs are provided for convenience only, may contain errors, and are not professional, engineering, legal or financial advice. You must verify any such output before relying on it, and QuotesDone is not liable for loss arising from reliance on automated outputs. QuotesDone does not guarantee that you will receive any quotation, or any particular number, price or quality of quotations.</p><h2>15. Payments, the payment processor, no escrow, and chargebacks</h2><p>The Reveal Fee and the card processing fee are charged by card or Apple Pay through our payment processor, Stripe, which is certified to the Payment Card Industry Data Security Standard (PCI DSS); QuotesDone does not store your full card details and is not liable for processor outages or errors. All amounts are in UAE Dirhams (AED) unless stated otherwise. Because a Reveal delivers value (the supplier&#39;s identity and contact details) immediately, the Reveal Fee and the card processing fee are non-refundable except as set out in section 5 (Refunds and non-responsive suppliers). Initiating a chargeback or payment dispute after a Reveal, other than for a genuine unauthorised transaction, is a breach of these Terms and entitles QuotesDone to suspend your account and recover the disputed amount and reasonable costs.</p><p><b>No escrow; QuotesDone does not hold your money.</b> The only payment QuotesDone collects is its own Reveal Fee and the card processing fee on it, charged through Stripe at the moment of Reveal. QuotesDone does not hold, escrow, receive, transmit or process any payment for the goods, works or services quoted between you and a Supplier. All payment for the actual job is arranged and settled directly between you and the Supplier, on terms agreed between you. QuotesDone is not a party to that contract and does not act as an escrow agent, payment institution, money-services business or stored-value provider in respect of those funds, and accepts no responsibility for the payment, non-payment, performance or quality of any job.</p><h2>16. Electronic acceptance and records</h2><p>Ticking the acceptance box or continuing to use the Platform constitutes a valid and binding electronic acceptance of these Terms under the laws of the United Arab Emirates. QuotesDone&#39;s records, including its acceptance logs and the signed acceptance certificate it generates, are admissible and, absent manifest error, conclusive evidence of the terms you accepted and when.</p><h2>17. Compliance and communications</h2><p>You warrant that you are not subject to sanctions and that your funds are lawful, and you will comply with applicable anti-money-laundering and sanctions laws. You consent to receive service and transactional communications, and (unless you opt out) promotional communications, by email, SMS and WhatsApp, and may unsubscribe from promotional messages at any time. Any feedback or suggestions you provide may be used by QuotesDone freely and without obligation.</p><h2>18. Complaints and dispute resolution</h2><p>If you have a complaint, please contact QuotesDone first at management@quotesdone.com or through the Platform. Every complaint receives a ticket number that you can track at <a href="/complaints/status/">quotesdone.com/complaints/status</a>. We will acknowledge your complaint within two (2) working days and give a substantive response within ten (10) working days, as set out in our <a href="/complaints/">Complaints Policy</a>. If your complaint is not resolved to your satisfaction, you may escalate it to the Consumer Rights channels of the Dubai Department of Economy and Tourism (DET), including the Dubai Consumer app, or to the UAE Ministry of Economy consumer hotline (800 1222). This complaints procedure does not affect your statutory rights or the governing law and jurisdiction set out below.</p><h2>19. Governing law and jurisdiction</h2><p>This document is governed by the laws of the United Arab Emirates, including the Commercial Transactions Law (Federal Decree-Law No. 50 of 2022), the Personal Data Protection Law (Federal Decree-Law No. 45 of 2021), the Electronic Transactions and Trust Services Law (Federal Decree-Law No. 46 of 2021), the Consumer Protection Law (Federal Law No. 15 of 2020) and its Implementing Regulation (Cabinet Resolution No. 66 of 2023), and the Civil Transactions Law (Federal Decree-Law No. 25 of 2025, in force from 1 June 2026, replacing Federal Law No. 5 of 1985). The courts of Dubai have jurisdiction.</p><h2>20. Contact</h2><p>This Platform is operated by QuotesDone Technologies, Trader License No. 1633275, Dubai, UAE. Questions about these Terms can be sent to info@quotesdone.com or management@quotesdone.com.</p><h2>Permitted use &amp; platform protection</h2><p>These provisions form part of the Customer Terms (Version 8, effective 15 September 2026) and are accepted at registration.</p><p>By registering and using QuotesDone, you agree that you will not: (a) access or use the Platform to build, design, benchmark or assist any competing product or service; (b) copy, scrape, harvest, republish or extract any supplier data, pricing, content or other materials from the Platform by any automated or manual means; or (c) reverse-engineer, decompile or replicate any part of the Platform&#39;s software, matching logic, anonymisation outputs or document templates. All such data and materials remain the exclusive property of QuotesDone.</p><p>Any breach of this clause entitles QuotesDone to immediate suspension or termination of the account, liquidated compensation of AED 10,000 per incident as a genuine pre-estimate of loss, recovery of any further proven losses, and injunctive relief to stop ongoing breach.</p></div><script>/*qdarfix*/(function(){if((localStorage.getItem('qd_lang')||'en')!=='ar')return;function run(){var c=document.querySelector('.crumb');if(c)c.innerHTML='<a href="/">الرئيسية</a> › القانوني › شروط الخدمة';document.querySelectorAll('.dochead .meta').forEach(function(m){m.innerHTML=m.innerHTML.replace('Version','الإصدار').replace('Last updated','آخر تحديث');});}if(document.readyState!=='loading')run();else document.addEventListener('DOMContentLoaded',run);})();</script>$qd_customer_terms$
 where slug = 'legal_terms_body';

-- ---------------------------------------------------------------- 2. the registry-held bodies
update public.legal_documents set body_html = $qd_privacy$<h1>Privacy Policy</h1><div class="muted">How QuotesDone Technologies collects, uses, shares and protects personal data on the QuotesDone anonymous quotation marketplace, and your rights under UAE Federal Decree-Law No. 45 of 2021 (the Personal Data Protection Law).</div><div class="card"><h2>1. Who We Are (Data Controller)</h2><p>This Privacy Policy explains how we handle your personal data when you use QuotesDone, an online B2B anonymous quotation marketplace.</p><p>The data controller is:</p><ul><li>QuotesDone Technologies, a Dubai Sole Establishment</li><li>DET Dubai Trader License No. 1633275</li><li>Owner: Ahmad Mhd Nabil Alzain</li><li>Address: Dubai, United Arab Emirates</li><li>Email: management@quotesdone.com; Phone: +971 50 931 9355 (the number on our licence record is +971 56 791 8605)</li></ul><p>We process personal data in accordance with the UAE Personal Data Protection Law, Federal Decree-Law No. 45 of 2021 (PDPL), and its implementing regime overseen by the UAE Data Office, which from June 2026 operates within the new UAE Federal Authority for Artificial Intelligence and Data. This policy applies to customers, suppliers and visitors. Where you act on behalf of a business, references to your personal data mean the personal data of the individuals concerned.</p><h2>2. Personal Data We Collect</h2><p>Depending on how you use the platform, we collect:</p><ul><li>Customer identity and contact data: your name, email address and mobile number, with the mobile number verified by one-time password (OTP).</li><li>Request content: the job or request you submit as text, voice recordings, photographs or drawings, including any personal data you choose to include.</li><li>Supplier data: business details and Know Your Customer (KYC) documents provided for vetting and onboarding.</li><li>Payment data: a payment reference returned by our payment processor, Stripe. We do not store full card numbers; card and Apple Pay details are handled by Stripe, which is certified to the Payment Card Industry Data Security Standard (PCI DSS).</li><li>Usage and technical data: logs, device and connection information, and records of platform activity.</li></ul><p>We do not intentionally collect special categories of data. Please avoid including sensitive details in request content unless necessary.</p><h2>3. Purposes and Lawful Bases</h2><p>We process personal data for clear purposes, each supported by a lawful basis under the PDPL:</p><ul><li>To create and manage your account, verify your mobile by OTP, and provide the marketplace, including matching requests to suppliers and enabling paid reveals (performance of a contract).</li><li>To calculate and collect the customer Reveal Fee of 3% of the quoted value at the point you choose to reveal a supplier, and to keep accounting records (performance of a contract and legal obligation). Suppliers pay no commission or success fee on jobs they win.</li><li>To vet suppliers and verify KYC documents, prevent fraud and misuse, secure the platform and improve our services (legitimate interests).</li><li>To share a chosen supplier&#x27;s contact details on a paid reveal, and for optional marketing (your consent, which you may withdraw at any time).</li></ul><p>Where we rely on legitimate interests, we balance these against your rights and interests.</p><h2>4. AI and Automated Processing</h2><p>QuotesDone uses automated tools, including artificial intelligence, to operate the marketplace. These tools:</p><ul><li>Structure and standardise the requests you submit (including converting voice, photos and drawings into a structured brief).</li><li>Match each request to vetted suppliers likely to be able to quote.</li><li>Summarise requests and quotes to make them easier to compare.</li></ul><p>This automated processing supports our service but does not produce binding legal effects on you without human involvement, and you remain free to accept, reject or ignore any quote. You may contact us to ask questions about, or object to, automated processing as described in the Your Rights section. Where automated processing could significantly affect individuals, we assess its impact before deploying it.</p><h2>5. How We Share Data</h2><p>Anonymity is central to QuotesDone. We share personal data only as follows:</p><ul><li>Request content is shared with matched suppliers WITHOUT revealing your identity, so suppliers can prepare anonymised quotes.</li><li>Your contact details are disclosed to a single supplier only after you pay the Reveal Fee and consent to the reveal for that chosen supplier; suppliers receive customer contact data only for jobs revealed to them.</li><li>Our payment processor, Stripe, receives the data needed to take payment (card or Apple Pay) and returns a payment reference.</li><li>Service providers (such as hosting, communications and analytics) process data on our behalf under written instructions.</li></ul><p>We may also disclose data where required by UAE law, a court of competent authority, or to protect our legal rights. We do not sell personal data.</p><h2>6. Cross-Border Transfers</h2><p>Some of our service providers may process personal data outside the United Arab Emirates. Where this happens, we apply the safeguards required by Articles 22 and 23 of the PDPL.</p><ul><li>We transfer data to countries the UAE Data Office recognises as providing an adequate level of protection; or</li><li>Where adequacy is not established, we rely on appropriate safeguards such as contractual clauses obliging the recipient to protect the data to UAE standards, or on your explicit consent, in each case in a manner that does not conflict with the public and security interests of the State.</li></ul><p>You may contact us for more information about the specific safeguards applied to a transfer.</p><h2>7. Data Retention</h2><p>We keep personal data only for as long as necessary for the purposes described above and to meet legal obligations.</p><ul><li>Account data is kept while your account is active and for a reasonable period afterwards.</li><li>Request content is retained to operate and improve matching, then deleted or anonymised when no longer needed.</li><li>Transaction and financial records, including Reveal Fee and registration-fee records, are retained for the periods required by UAE accounting and tax law.</li><li>Supplier KYC documents are retained for the duration of the relationship and any legally required period thereafter.</li><li>Logs are kept for limited periods for security and audit purposes.</li></ul><p>When a retention period ends, we securely delete or irreversibly anonymise the data. Our internal Data Protection and Retention Policy sets out the detailed schedule.</p><h2>8. Your Rights Under the PDPL</h2><p>Subject to the conditions and exceptions in the PDPL, you have the right to:</p><ul><li>Access your personal data and obtain information about how it is processed.</li><li>Request correction of inaccurate or incomplete data.</li><li>Request deletion of your data where the legal grounds apply.</li><li>Object to, or request restriction of, certain processing, including processing based on legitimate interests and certain automated processing.</li><li>Request that your personal data be provided to you, or transferred to another controller, in a structured, commonly used, machine-readable format (data portability), where technically feasible.</li><li>Request that your data be transferred to you or another controller in a structured format, where applicable.</li><li>Withdraw consent at any time, without affecting processing carried out before withdrawal.</li></ul><p>To exercise any right, contact us at management@quotesdone.com. We will respond within the timeframes required by the PDPL. If you are not satisfied, you may lodge a complaint with the UAE Data Office.</p><h2>9. Electronic Marketing and Communications</h2><p>We send transactional messages you need to use the service — for example mobile one-time passwords (OTP), request and quote notifications, and account or payment confirmations — on the basis of our contract with you; these are not marketing.</p><p>We send marketing or promotional messages by email, SMS or other electronic means only where you have given consent, and you can withdraw consent or unsubscribe at any time using the link or instructions in the message, or by emailing management@quotesdone.com. We handle electronic communications in line with the UAE telecommunications and electronic-marketing rules overseen by the Telecommunications and Digital Government Regulatory Authority (TDRA) and the Electronic Transactions and Trust Services Law (Federal Decree-Law No. 46 of 2021). We do not sell your contact details for third-party marketing.</p><h2>10. Security</h2><p>We apply appropriate technical and organisational measures to protect personal data against unauthorised access, loss, alteration or disclosure, consistent with the PDPL and the Electronic Transactions and Trust Services Law, Federal Decree-Law No. 46 of 2021.</p><ul><li>Access to personal data is restricted to authorised personnel on a need-to-know basis.</li><li>We use encryption in transit, OTP verification for customer mobile numbers, and segregation of anonymised request content from identity data.</li><li>Payment card data is handled by Stripe, our PCI DSS–certified payment processor, and is not stored by us.</li></ul><p>No system can be guaranteed to be completely secure. If a personal data breach occurs that meets the legal threshold, we will notify the UAE Data Office and affected individuals as required by the PDPL.</p><h2>11. Children, Changes and Contact</h2><p>QuotesDone is a business-to-business platform intended for users aged 18 and over. It is not directed at minors, and we do not knowingly collect personal data from children. If you believe a minor has provided us data, please contact us so we can delete it.</p><p>We may update this Privacy Policy from time to time to reflect changes in our services or the law. The current version is always available on our platform, and material changes will be notified where appropriate.</p><p>For any privacy question, to exercise your rights, or to reach our data protection contact, please use:</p><ul><li>Email: management@quotesdone.com</li><li>Phone: +971 50 931 9355 (licence record: +971 56 791 8605)</li><li>Post: QuotesDone Technologies, Dubai, United Arab Emirates (our DET Trader License is for an online business with no shop front, so there is no street address)</li></ul><p>This policy is governed by the laws of the UAE, and disputes are subject to the courts of Dubai.</p></div>$qd_privacy$
 where slug = 'privacy';

update public.legal_documents set body_html = $qd_refund_policy$<h1>Refund &amp; Cancellation Policy</h1><div class="muted">Explains when the QuotesDone Reveal Fee and card processing fee are and are not refundable, how to request a refund, processing times and method, supplier registration-fee terms, and your preserved statutory rights under UAE Federal Law No. 15 of 2020.</div><div class="card"><h2>1. About This Policy</h2><p>This Refund &amp; Cancellation Policy applies to QuotesDone, an online business-to-business quotation marketplace operated by QuotesDone Technologies (Dubai Sole Establishment; DET Dubai Trader License No. 1633275), Dubai, United Arab Emirates.</p><p>QuotesDone is a marketplace and facilitator only. We connect customers with suppliers and provide anonymised quotations. We are not a contractor, supplier or party to the works quoted, and this Policy governs only the fees you pay to QuotesDone, not amounts payable to a supplier under any separate contract you enter into.</p><p>This Policy must be read together with our Terms &amp; Conditions. It is governed by the laws of the UAE and applied without prejudice to your non-waivable statutory rights under Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023).</p><h2>2. The Reveal Fee</h2><p>To unlock the identity and contact details of a chosen supplier behind an anonymised quotation, you pay a Reveal Fee equal to 3% of the quoted amount, plus a card processing fee that covers what our payment processor charges to take the payment. No cap applies to the Reveal Fee. Both amounts and the total are shown to you before you pay. QuotesDone is not registered for VAT, and no VAT is charged on either.</p><p>The Reveal Fee and the card processing fee are charges for the reveal service provided by QuotesDone. They are separate from, and additional to, any price agreed between you and the supplier for the actual goods, services or works.</p><p>Because the Reveal Fee unlocks supplier information immediately on payment, it is generally treated as earned once the reveal is delivered, subject to the specific refund right described below and to your statutory rights under UAE law.</p><h2>3. When a Reveal Is Refunded</h2><p>We refund everything you paid for a reveal in one defined circumstance: where a revealed supplier does not respond to you within five (5) working days of your payment and does not respond to QuotesDone&#39;s CEO&#39;s final call. You do not need to prove anything for the clock to start: we track every reveal from the moment you pay. If the supplier has not responded within three (3) working days, we chase the supplier on your behalf and copy you; if there is still no response on the fifth (5th) working day, the case goes to QuotesDone&#39;s CEO for a final call; if the supplier does not respond to that call, the refund is issued.</p><p>If you have tried to reach the supplier yourself, dated copies of emails, messages sent through the Platform, or call logs help us close the case faster, but they are not a condition of the refund. Working days are Monday to Friday, excluding UAE public holidays.</p><p>If these conditions are met, everything you paid to reveal that supplier is refunded: the Reveal Fee and the card processing fee. The CEO&#39;s decision, whichever way it goes, is recorded against your refund case reference and the decision reference, and both are shown to you in your account and quoted when we confirm the outcome. This refund right is in addition to any remedy available to you under Federal Law No. 15 of 2020 on Consumer Protection.</p><h2>4. When a Reveal Is Not Refunded</h2><p>The Reveal Fee and card processing fee are not refundable once the revealed supplier has responded to you within the five-working-day window, as the reveal service has then been fully delivered and the supplier has engaged.</p><p>The Reveal Fee and card processing fee are not refundable for a change of mind, for example where you decide not to proceed with a supplier who did respond, where you select a different supplier, or where the supplier&#x27;s pricing or terms no longer suit you.</p><p>The Reveal Fee and card processing fee are not refundable where the supplier responded to you or to QuotesDone within the five-working-day window. Nothing in this section limits your non-waivable rights under UAE consumer protection law where they apply.</p><h2>5. How to Request a Refund</h2><p>You do not need to submit a request for a non-response refund: the ladder above runs automatically from the moment you pay. You can still tell us at any time that the supplier is not responding, by emailing management@quotesdone.com or by using the support function on the Platform, and we will chase the supplier immediately.</p><p>If you do write to us, your account email and the reveal reference are enough. Proof of your own attempts to reach the supplier (emails, Platform messages or call logs) is optional: it can help us close the case faster, but it is never a condition of the refund (see section 3).</p><p>We may ask for further information to identify your reveal. Providing complete and accurate information helps us assess and process eligible refunds promptly.</p><h2>6. Processing Time and Method</h2><p>Once QuotesDone&#39;s CEO decides a refund, it is issued to the original payment method through our payment processor, Stripe, and we confirm it to you with your refund case reference. Banks and card issuers usually take seven (7) to fourteen (14) working days to show the refund on your statement.</p><p><b>Payments handled by Stripe · PCI DSS.</b> Your card or Apple Pay payment is processed by Stripe, a payment processor certified to the Payment Card Industry Data Security Standard; QuotesDone never sees or stores your full card number.</p><p>Refunds are made in the currency of the original payment and for everything you paid for the reveal: the Reveal Fee and the card processing fee. QuotesDone deducts nothing from your refund and bears the payment processor&#39;s costs itself. What QuotesDone recovers under the Supplier Agreement (the amount refunded to you, an administrative fee of AED 250 and interest at 9% per annum) is charged to the supplier whose non-response caused the refund, never to you.</p><p>If a refund cannot be returned to the original payment method for reasons outside our control, we will agree an alternative lawful method with you.</p><h2>7. Supplier Registration-Fee Terms</h2><p>Suppliers may be charged a registration fee to join and maintain a profile on the Platform. QuotesDone charges suppliers no commission, success fee or transaction fee on jobs they win. These terms apply to suppliers, not to customers.</p><p>Any supplier registration fee is charged for access to the marketplace and listing services over the registration period. Where a fee covers a defined period, it is generally non-refundable for the unused portion once access has been granted, except where required by law or expressly agreed in writing.</p><h2>8. Your Statutory Rights</h2><p>Nothing in this Policy excludes, restricts or waives any right you may have under Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023), or under other applicable UAE law.</p><p>Where a service is not provided as described, your statutory remedies under UAE consumer protection law continue to apply alongside the contractual refund right in this Policy.</p><p>If you believe your consumer rights have not been honoured, you may contact us first and, if unresolved, escalate to the relevant authority as set out in our Complaints &amp; Dispute Resolution Policy.</p></div>$qd_refund_policy$
 where slug = 'refund-policy';

update public.legal_documents set body_html = $qd_disclaimer$<h1>Disclaimer &amp; Limitation of Liability</h1><div class="muted">Confirms QuotesDone&#x27;s marketplace/intermediary status, exactly which supplier checks QuotesDone performs and the absence of warranties beyond them on quality, pricing or completion, your due-diligence responsibility, and a limitation of liability to fees paid, with carve-outs for fraud, gross negligence and non-waivable UAE consumer and legal rights.</div><div class="card"><h2>1. About This Disclaimer</h2><p>This Disclaimer &amp; Limitation of Liability applies to QuotesDone, operated by QuotesDone Technologies (Dubai Sole Establishment; DET Dubai Trader License No. 1633275), Dubai, United Arab Emirates.</p><p>It forms part of our Terms &amp; Conditions and should be read together with our Refund &amp; Cancellation Policy and Complaints &amp; Dispute Resolution Policy.</p><p>It is governed by the laws of the UAE, including Federal Law No. 15 of 2020 on Consumer Protection, the Federal Decree-Law No. 50 of 2022 on Commercial Transactions and the Civil Transactions Law (Federal Decree-Law No. 25 of 2025), and is applied subject to your non-waivable statutory rights.</p><h2>2. Marketplace / Intermediary Status</h2><p>QuotesDone is an online marketplace and intermediary that provides anonymised supplier quotations and a reveal service. We are not a contractor, supplier, agent or party to any contract for goods, services or works formed between a customer and a supplier.</p><p>Any contract for the actual goods, services or works is entered into directly between the customer and the chosen supplier, on terms agreed between them. We are not responsible for performing, supervising or guaranteeing that contract.</p><p>Our role is limited to operating the Platform and facilitating connections between customers and suppliers.</p><h2>3. No Warranty on Suppliers or Quotes</h2><p>Before a supplier can be matched, QuotesDone checks the mandatory six (business name, mobile number, email address, trade licence, company profile and signed Supplier Agreement) and, on the trade licence, the licence number, issuing authority and expiry date, as published at <a href="/how-we-verify/">How we verify suppliers</a>. That is what &quot;verified&quot; and &quot;licence-checked&quot; mean on QuotesDone. The check confirms the licence as presented on the date it was made; it does not guarantee that the licence covers your specific works.</p><p>Beyond those checks, we do not warrant or guarantee the qualifications, conduct, workmanship, solvency, insurance, quality, pricing, availability or completion of any supplier or the works they quote for.</p><p>Quotations provided through the Platform are indicative only. Final scope, price and terms are a matter for direct agreement between you and the supplier, and may differ from the indicative quote.</p><p>While we take reasonable steps to operate the Platform properly, the Platform and its content are provided on an &quot;as is&quot; and &quot;as available&quot; basis to the extent permitted by UAE law.</p><h2>4. Customer Due-Diligence Responsibility</h2><p>You are responsible for carrying out your own due diligence on any supplier before entering into a contract, including confirming that their trade licence covers your specific works and checking permits, insurance, references, pricing and suitability for your requirements.</p><p>You should satisfy yourself as to the terms of any contract you enter into with a supplier and should not rely on QuotesDone to assess or approve the supplier on your behalf.</p><p>Paying the Reveal Fee unlocks supplier contact details; it is not an endorsement or recommendation of the supplier. The only verification QuotesDone performs is the one described at <a href="/how-we-verify/">How we verify suppliers</a>; everything beyond it, including whether the licence covers your specific works, permits, insurance and references, remains yours to check.</p><h2>5. Limitation of Liability</h2><p>To the maximum extent permitted by UAE law, our total aggregate liability to you arising out of or in connection with the Platform and our services is limited to the total fees you have actually paid to QuotesDone for the relevant transaction giving rise to the claim.</p><p>To the extent permitted by law, we are not liable for indirect, incidental, special or consequential loss, loss of profit, loss of business or loss of opportunity, or for the acts, omissions, defaults or insolvency of any supplier.</p><p>These limitations reflect the nature of QuotesDone as a marketplace intermediary and the fees charged for our reveal service.</p><h2>6. Carve-Outs and Non-Waivable Rights</h2><p>Nothing in this Disclaimer excludes or limits our liability for fraud, fraudulent misrepresentation, gross negligence or wilful misconduct, or for death or personal injury caused by our negligence, or for any other liability that cannot lawfully be excluded.</p><p>Nothing in this Disclaimer excludes, restricts or waives any non-waivable right or remedy you have under Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023), or under other mandatory provisions of UAE law.</p><p>Where any provision of this Disclaimer is found to be unenforceable, the remaining provisions continue in full force and effect.</p></div>$qd_disclaimer$
 where slug = 'disclaimer';

update public.legal_documents set body_html = $qd_complaints_policy$<h1>Complaints &amp; Dispute Resolution Policy</h1><div class="muted">Sets out how to raise a complaint with QuotesDone, our acknowledgement and resolution timelines, the escalation path, our facilitation-only role in customer-supplier disputes, and your right to escalate to the relevant UAE authority and the courts of Dubai.</div><div class="card"><h2>1. About This Policy</h2><p>This Complaints &amp; Dispute Resolution Policy applies to QuotesDone, operated by QuotesDone Technologies (Dubai Sole Establishment; DET Dubai Trader License No. 1633275), Dubai, United Arab Emirates.</p><p>We are committed to handling complaints fairly, promptly and in line with Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023).</p><p>This Policy explains how to raise a complaint about the QuotesDone Platform or our services, how we respond, and your rights to escalate, including to the relevant UAE authority and the courts of Dubai.</p><h2>2. How to Raise a Complaint</h2><p>You can raise a complaint by emailing management@quotesdone.com or by sending a message marked as a complaint through our <a href="/contact/">contact form</a>. Every complaint receives a ticket number, and you can follow its status (acknowledged, in review, final response) at <a href="/complaints/status/">quotesdone.com/complaints/status</a> using the ticket number and your email address.</p><p>To help us assist you quickly, please include your name and account details, the relevant quotation, reveal or supplier reference, a clear description of the issue, the outcome you are seeking, and any supporting evidence such as emails, Platform messages, screenshots or receipts.</p><p>We treat all complaints confidentially and handle personal data in accordance with Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data and our Privacy Policy.</p><h2>3. Acknowledgement and Resolution Timelines</h2><p>We aim to acknowledge your complaint within two (2) working days of receipt and to provide a substantive response or resolution within ten (10) working days.</p><p>Where a complaint is complex or requires information from a third party, we will tell you and provide a revised timeframe, keeping you updated on progress.</p><p>Working days exclude Saturdays, Sundays and UAE public holidays. We maintain records of complaints and their outcomes to help us improve our service.</p><h2>4. Our Role in Customer-Supplier Disputes</h2><p>QuotesDone is a marketplace and facilitator only. We are not a contractor, supplier or party to any contract for goods, services or works formed between a customer and a supplier through the Platform.</p><p>Where a dispute concerns the supplier&#x27;s quote, pricing, quality, licensing, conduct or completion of works, that is a matter between you and the supplier. Our role is limited to reasonable facilitation, such as sharing relevant Platform records or helping reconnect the parties.</p><p>Complaints that relate to the QuotesDone Platform itself, such as the Reveal Fee, the reveal service or account matters, are handled directly by us under this Policy.</p><h2>5. Escalation Path</h2><p>If you are not satisfied with our initial response, you may ask for your complaint to be reviewed by QuotesDone&#39;s CEO by replying to our response or emailing management@quotesdone.com and marking your message for escalation.</p><p>We will conduct a further review and aim to provide a final written response, setting out our position and the reasons for it, together with the external escalation routes in section 6.</p><p>If the matter remains unresolved after this internal escalation, you may pursue the external options described below.</p><h2>6. Escalating to UAE Authorities</h2><p>Because QuotesDone is licensed in Dubai, you may refer an unresolved consumer complaint to the Department of Economy and Tourism (DET) in Dubai through its Consumer Protection / Consumer Rights channels (including the Dubai Consumer App and website).</p><p>You may also contact the UAE Ministry of Economy consumer protection service, including its consumer hotline (800 1222), which receives and coordinates consumer complaints with the competent authorities.</p><p>These authorities handle complaints under Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023). Referring a matter to them does not affect your other legal rights.</p><h2>7. Governing Law and Courts</h2><p>This Policy and any dispute arising from your use of QuotesDone are governed by the laws of the United Arab Emirates, including the Federal Decree-Law No. 50 of 2022 on Commercial Transactions and the Civil Transactions Law (Federal Decree-Law No. 25 of 2025) where applicable.</p><p>Subject to any mandatory consumer protection provisions and to the authority referral options above, the courts of Dubai have jurisdiction over disputes between you and QuotesDone.</p><p>Nothing in this Policy prevents you from exercising any non-waivable statutory right or from seeking the remedies available to you under applicable UAE law.</p></div>$qd_complaints_policy$
 where slug = 'complaints-policy';

update public.legal_documents set body_html = $qd_acceptable_use$<h1>Acceptable Use Policy</h1><div class="muted">Defines permitted and prohibited conduct on the QuotesDone Platform, including accuracy of information, prohibitions on fraud, abuse, scraping, circumvention, IP infringement and off-platform identification of suppliers before reveal, the consequences of breach, and how to report misuse.</div><div class="card"><h2>1. About This Policy</h2><p>This Acceptable Use Policy applies to all users of QuotesDone, operated by QuotesDone Technologies (Dubai Sole Establishment; DET Dubai Trader License No. 1633275), Dubai, United Arab Emirates.</p><p>By accessing or using the Platform, you agree to use it lawfully and in line with this Policy, our Terms &amp; Conditions and applicable UAE law.</p><p>This Policy supports the integrity of the anonymous-quotation model, which depends on accurate information and on supplier identities remaining protected until a Reveal Fee is paid.</p><h2>2. Permitted Conduct</h2><p>You may use QuotesDone to request, receive and compare anonymised quotations, to pay the applicable Reveal Fee to unlock a chosen supplier, and to communicate with suppliers for genuine, lawful business purposes.</p><p>You must provide accurate, current and complete information when registering, submitting requirements and requesting quotations, and keep your account details up to date.</p><p>You must keep your login credentials secure and are responsible for activity carried out under your account.</p><h2>3. Prohibited Conduct</h2><p>You must not use the Platform for any unlawful, fraudulent or deceptive purpose, submit false, misleading or fictitious requests or quotations, or impersonate any person or business.</p><p>You must not abuse, harass, threaten or defame other users or our staff, post unlawful, infringing or offensive content, or upload malware or anything that could harm the Platform or its users.</p><p>You must not infringe the intellectual property or other rights of QuotesDone or any third party, including by copying, reproducing or exploiting Platform content without authorisation.</p><h2>4. No Scraping or Circumvention</h2><p>You must not scrape, harvest, crawl, data-mine or use automated means to extract data from the Platform, nor attempt to access areas, accounts or data you are not authorised to access.</p><p>You must not interfere with or circumvent the security, anonymisation, payment or reveal mechanisms of the Platform, or take any action designed to avoid paying the Reveal Fee.</p><p>You must not reverse engineer, disrupt, overload or otherwise compromise the Platform&#x27;s normal operation.</p><h2>5. Protecting Supplier Anonymity</h2><p>The Platform anonymises supplier identities until you pay the Reveal Fee. You must not attempt to identify, contact or deal with a supplier off-platform before reveal, including by deducing or researching a supplier&#x27;s identity from a quotation.</p><p>You must not, after a reveal, deal with a supplier in a way designed to deprive QuotesDone of the Reveal Fee, such as deliberately taking a transaction off the Platform to avoid charges.</p><p>These rules protect the fairness of the marketplace for both customers and suppliers and form an essential condition of using the Platform.</p><h2>6. Consequences of Breach</h2><p>If you breach this Policy, we may, at our discretion and proportionate to the breach, issue a warning, restrict features, suspend or terminate your account, remove content, or withhold a reveal.</p><p>Serious or unlawful conduct, including fraud, circumvention of fees, intellectual property infringement or unlawful content, may result in legal action and referral to the competent UAE authorities.</p><p>We may retain and use relevant records as evidence to the extent permitted by Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data and other applicable UAE law.</p><h2>7. Reporting Misuse</h2><p>If you become aware of any breach of this Policy, suspected fraud, security vulnerability or other misuse of the Platform, please report it to us at management@quotesdone.com or through the Platform&#x27;s reporting function.</p><p>Please include enough detail to allow us to investigate, such as the accounts, quotations or messages involved and any supporting evidence.</p><p>We take reports seriously, investigate appropriately, and may cooperate with the competent UAE authorities where required by law.</p></div>$qd_acceptable_use$
 where slug = 'acceptable-use';

-- ---------------------------------------------------------------- 3. version, date and hash of all six
update public.legal_documents
   set version = 'v8', effective_date = date '2026-09-15',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'customer-terms';
update public.legal_documents
   set version = '1.4', effective_date = date '2026-09-15',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'privacy';
update public.legal_documents
   set version = '1.6', effective_date = date '2026-09-15',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'refund-policy';
update public.legal_documents
   set version = '1.2', effective_date = date '2026-09-15',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'disclaimer';
update public.legal_documents
   set version = '1.3', effective_date = date '2026-09-15',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'complaints-policy';
update public.legal_documents
   set version = '1.3', effective_date = date '2026-09-15',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'acceptable-use';

-- ---------------------------------------------------------------- 4. the customer pins and label follow the registry
update public.app_secrets set value = (select encode(sha256(convert_to(html, 'UTF8')), 'hex') from public.pages where slug = 'legal_terms_body'), updated_at = now()
 where key = 'terms_sha256_customer';
update public.app_secrets set value = (select version from public.legal_documents where slug = 'customer-terms'), updated_at = now()
 where key in ('customer_terms_version', 'terms_sha256_customer_version');
update public.app_secrets s
   set value = d.title || ' — Version ' || ltrim(d.version, 'vV'), updated_at = now()
  from public.legal_documents d
 where s.key = 'customer_terms_label' and d.slug = 'customer-terms';

-- ---------------------------------------------------------------- 5. the knowledge every seat reads
-- The number is matched by shape, never spelled, so scripts/checks/the_register_number_the_licence_does_not_print_appears_nowhere
-- cannot find it in this file. Three shapes are in production: a "Register : ..." line, "; <register> No. <n>" and " · CR <n>".
update public.agent_knowledge
   set content = regexp_replace(regexp_replace(content,
         E'\\n  Register   : Commercial Register[[:space:]]No\\. [0-9]{7}', '', 'g'),
         '(; Commercial Register[[:space:]]No\. | · CR )[0-9]{7}', '', 'g'),
       updated_at = now()
 where strpos(content, '2883' || '503') > 0;
update public.kb_chunks
   set content = regexp_replace(regexp_replace(content,
         E'\\n  Register   : Commercial Register[[:space:]]No\\. [0-9]{7}', '', 'g'),
         '(; Commercial Register[[:space:]]No\. | · CR )[0-9]{7}', '', 'g'),
       embedding_gte = null, embed_claimed_at = null
 where strpos(content, '2883' || '503') > 0;

-- ---------------------------------------------------------------- 6. the file proves what the checks will read
do $check$
declare r record; n int; v text;
begin
  for r in select * from (values
    ('customer-terms', 'v8', date '2026-09-15', '6168db6bad542d7fac4969fec483e0156e27ede35d6ba218e40c431c0b752ded'),
    ('privacy', '1.4', date '2026-09-15', '0e8966af891352f3669d773b2c743730f531947235ae0bf8ada8dd4016cb6eb5'),
    ('refund-policy', '1.6', date '2026-09-15', '9a9b3d4db267b867f1c12b001e2a29eb2821bf19bf3c0fee1d4c8f2e8c2f93e7'),
    ('disclaimer', '1.2', date '2026-09-15', 'c0041115714b81fb6cdf5f0865497230a8df72594025b4a76c67c927c85082e8'),
    ('complaints-policy', '1.3', date '2026-09-15', '1768f436a3f258d4e55a2a70ce103ad1efdeba604a9e5dd4d99b9caf2e6eb87d'),
    ('acceptable-use', '1.3', date '2026-09-15', '87fdf0bf514e77f417c52ac31f50a2c72132db909458dbba4d648f8d7481da50')
  ) as t(slug, version, eff, sha) loop
    select count(*) into n from public.legal_documents d
     where d.slug = r.slug and d.version = r.version and d.effective_date = r.eff
       and d.content_sha256 = r.sha and encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex') = r.sha;
    if n <> 1 then raise exception 'legal_documents.% is not % / % / %', r.slug, r.version, r.eff, r.sha; end if;
  end loop;

  -- the number and the wording are gone from every store this file owns
  select count(*) into n from public.legal_documents where body_html ~ '288350[3]' or body_html ~* 'commercial register[[:space:]]+no';
  if n <> 0 then raise exception '% legal_documents row(s) still print the register number', n; end if;
  select count(*) into n from public.pages where html ~ '288350[3]' or html ~* 'commercial register[[:space:]]+no';
  if n <> 0 then raise exception '% pages row(s) still print the register number', n; end if;
  select count(*) into n from public.agent_knowledge where strpos(content, '2883' || '503') > 0;
  if n <> 0 then raise exception '% agent_knowledge row(s) still carry the register number', n; end if;
  select count(*) into n from public.kb_chunks where strpos(content, '2883' || '503') > 0;
  if n <> 0 then raise exception '% kb_chunks row(s) still carry the register number', n; end if;

  -- the signed bodies name the registry version (scripts/checks/the_refund_ladder_texts_agree test 2)
  select count(*) into n from (
    select d.slug, d.version, (regexp_matches(p.html, 'Version (v?[0-9]+)', 'g'))[1] as named
      from public.legal_documents d join public.pages p on p.slug = replace(d.source, 'pages:', '')
     where d.source like 'pages:%') x
   where ltrim(x.named, 'vV') <> ltrim(x.version, 'vV');
  if n <> 0 then raise exception '% signed-body version label(s) disagree with the registry', n; end if;

  -- the customer pins, the live signed body and the published page agree, and none is null
  if exists (
    select 1 from (select (select value from public.app_secrets where key = 'customer_terms_version') dv,
                          (select value from public.app_secrets where key = 'terms_sha256_customer_version') pv,
                          (select value from public.app_secrets where key = 'terms_sha256_customer') psha,
                          (select encode(sha256(convert_to(html, 'UTF8')), 'hex') from public.pages where slug = 'legal_terms_body') lsha) s
     where dv is null or pv is null or psha is null or lsha is null or psha <> lsha or dv <> pv or dv <> 'v8')
  then raise exception 'customer terms pins are not intact'; end if;
  if (select value from public.app_secrets where key = 'terms_sha256_customer') <> '6168db6bad542d7fac4969fec483e0156e27ede35d6ba218e40c431c0b752ded' then raise exception 'customer pin is not the generated body'; end if;
  select value into v from public.app_secrets where key = 'customer_terms_label';
  if v not like '%Version 8' then raise exception 'customer_terms_label is %', v; end if;

  raise notice 'registry re-issued without the register number: %', 'customer-terms v8, privacy 1.4, refund-policy 1.6, disclaimer 1.2, complaints-policy 1.3, acceptable-use 1.3';
end
$check$;

commit;
